// Ambil semua item dari node sebelumnya
const allItems = $input.all();
const rows = allItems.map(item => item.json);

// Filter: hanya pending dan resolved (bukan reported)
const activeRows = rows.filter(r =>
  r.Status === 'pending' || r.Status === 'resolved'
);

// Kalau tidak ada item aktif, return signal kosong
if (activeRows.length === 0) {
  return [{ json: { hasItems: false, waMessage: '', resolvedRows: [] } }];
}

// ── Group by Nama_Project ──────────────────────────────────────
const projects = {};
activeRows.forEach(row => {
  const proj = row.Nama_Project || 'Tidak Diketahui';
  if (!projects[proj]) projects[proj] = [];
  projects[proj].push(row);
});

// ── Format tanggal hari ini ─────────────────────────────────────
const now = new Date();
const formattedDate = now.toLocaleDateString('id-ID', {
  day: '2-digit', month: '2-digit', year: '2-digit'
});

// ── Build pesan WhatsApp ────────────────────────────────────────
const numberEmojis = ['1️⃣','2️⃣','3️⃣','4️⃣','5️⃣','6️⃣','7️⃣','8️⃣','9️⃣','🔟'];

let msg = `📋 *Daftar Komplain & Tambahan Salero Dindo (${formattedDate})*\n\n`;

const projectNames = Object.keys(projects);
projectNames.forEach((proj, idx) => {
  const emoji = numberEmojis[idx] || `${idx + 1}.`;
  msg += `${emoji} *${proj}*\n`;

  projects[proj].forEach(item => {
    // Tanda resolved
    const resolvedMark = item.Status === 'resolved' ? ' ✅' : '';

    // Tanggal komplain (dd/MM)
    let tglStr = '';
    if (item.Tanggal_Komplain) {
      const parts = String(item.Tanggal_Komplain).split('-');
      if (parts.length === 3) {
        tglStr = ` (${parts[2]}/${parts[1]}/${parts[0].slice(2)})`;
      }
    }

    // Prioritas tinggi → tandai
    const highMark = item.Prioritas === 'Tinggi' ? ' 🔴' : '';

    msg += `• ${item.Komplain}${tglStr}${resolvedMark}${highMark}\n`;
  });

  msg += '\n';
});

msg += `━━━━━━━━━━━━━━━\n`;

// Summary
const total    = activeRows.length;
const resolved = activeRows.filter(r => r.Status === 'resolved').length;
const pending  = activeRows.filter(r => r.Status === 'pending').length;

msg += `📊 *Summary:* Total ${total} | ✅ Selesai: ${resolved} | ⏳ Pending: ${pending}\n\n`;
msg += `_Catatan: Setiap outlet diberikan CCTV dan Speaker (nanti akan di-info kembali tempatnya)_\n\n`;
msg += `_Dikirim otomatis setiap hari pukul 08.00 WIB_`;

// ── Kumpulkan resolved rows untuk diupdate statusnya ────────────
const resolvedRows = activeRows
  .filter(r => r.Status === 'resolved')
  .map(r => ({
    row_number: r.row_number,
    ID: r.ID
  }));

return [{
  json: {
    hasItems:    true,
    waMessage:   msg,
    resolvedRows: resolvedRows,
    summary: { total, resolved, pending }
  }
}];

// Ambil list resolved rows dari pesan yang sudah dikirim
const resolvedRows = $('Format Pesan Rekapan').item.json.resolvedRows || [];

// Kalau tidak ada yang resolved, return array kosong (workflow berhenti)
if (resolvedRows.length === 0) {
  return [];
}

// Output 1 item per resolved row untuk diupdate satu-satu
return resolvedRows.map(row => ({
  json: {
    row_number: row.row_number,
    Status:     'reported'
  }
}));

// Tidak ada komplain aktif hari ini - workflow berhenti di sini
console.log('[Salero Dindo] Tidak ada komplain pending/resolved hari ini. Tidak ada WA yang dikirim.');
return [{ json: { skipped: true, reason: 'Tidak ada komplain aktif' } }];
